  "news_id": "N:doc-5",
  "company_id": "U_19717",
  "headline": "Запрет на экспорт бензина до конца года стабилизирует ваши закупочные цены на топливо",
  "impact_type": "opportunity",
  "importance": "medium",
  "confidence": "medium",
  "what_happened": [
    {"text": "Правительство продлило временный запрет на экспорт бензина для производителей до 31 декабря.", "origin": "fact", "source_ids": ["N:doc-5"]},
    {"text": "По оценке правительства, мера должна снизить оптовые цены на топливо на внутреннем рынке; для сетей АЗС это может означать стабилизацию закупочных цен.", "origin": "fact", "source_ids": ["N:doc-5"]}
  ],
  "why_it_matters": [
    {"text": "Основной вид деятельности вашей компании — розничная торговля моторным топливом, а ключевое сырьё — бензин и дизельное топливо, поэтому оптовые цены напрямую формируют вашу закупочную себестоимость и маржу.", "origin": "ai", "source_ids": ["F:MAINOKVED_NAME", "F:RAW_MATERIALS", "N:doc-5"]},
    {"text": "Ваши ключевые поставщики — нефтеперерабатывающие заводы и нефтебазы, а также оптовый трейдер топлива: продление запрета увеличивает предложение бензина на внутреннем рынке и снижает риск ценовых скачков при закупках.", "origin": "ai", "source_ids": ["F:KEY_SUPPLIERS", "P:U_9000006", "P:U_9000007", "N:doc-5"]},
    {"text": "Среди ваших покупателей — транспортные компании и автосервис: стабильные розничные цены поддерживают спрос со стороны перевозчиков и снижают риск переключения клиентов на конкурентов из-за ценовых перепадов.", "origin": "ai", "source_ids": ["F:KEY_CLIENTS", "P:U_9000008", "P:U_9000025", "N:doc-5"]}
  ],
  "consequences": [
    {"text": "Стабилизация или снижение оптовых цен на бензин до конца года может улучшить валовую маржу сети АЗС при сохранении розничных цен; эффект зависит от того, как быстро производители пересмотрят отпускные цены.", "kind": "opportunity", "level": "medium", "horizon": "short", "origin": "ai", "source_ids": ["N:doc-5", "F:RAW_MATERIALS"]},
    {"text": "Мера действует только до 31 декабря: после отмены запрета возможен возврат роста оптовых цен, что создаст риск для маржи и потребности в пересмотре розничных цен в начале следующего года.", "kind": "risk", "level": "medium", "horizon": "medium", "origin": "ai", "source_ids": ["N:doc-5"]},
    {"text": "По оценке Альфа-Банка, спрос в розничной торговле замедляется на пике потребления — даже при стабильных закупочных ценах рост выручки может ограничить охлаждение спроса, в том числе со стороны транспортных компаний.", "kind": "factor", "level": "medium", "horizon": "short", "origin": "ai", "source_ids": ["A:BA-17:0", "F:KEY_CLIENTS"]}
  ],
  "actions": [
    {"text": "Пересмотреть условия закупок с нефтебазами и НПЗ на период действия запрета: зафиксировать графики поставок и цены, чтобы использовать окей стабильных оптовых цен до 31 декабря.", "type": "action", "bank_product": null, "source_ids": ["N:doc-5", "F:KEY_SUPPLIERS"]},
    {"text": "Сценарий: если после 31 декабря запрет не продлят и оптовые цены вырастут, оценить запас по марже и заранее подготовить план пересмотра розничных цен и закупок на первый квартал.", "type": "scenario", "bank_product": null, "source_ids": ["N:doc-5"]},
    {"text": "Использовать период стабильных закупочных цен для планирования оборотного финансирования под закупки топлива: проверить, как текущая кредитная нагрузка группы соотносится с сезонными закупками в начале года.", "type": "question", "bank_product": "оборотное финансирование", "source_ids": ["F:CL_PRODUCT_LOA_MARK", "G:group_3_sb", "N:doc-5"]}
  ],
  "bank_view": [
    {"text": "По прогнозу Альфа-Банка на 2026 год, объёмы экспорта не пересматриваются: дополнительные доходы могут не реализоваться из-за логистики и санкционных рисков (прогноз экспорта — $480 млрд).", "origin": "bank", "source_ids": ["A:BA-17:0"]},
    {"text": "Альфа-Банк отмечает существенный пересмотр вверх ожиданий роста товарного импорта за 5 месяцев 2026 года (рост на 11% г/г, прогноз $340 млрд), что говорит о восстановлении доли импорта к ВВП.", "origin": "bank", "source_ids": ["A:BA-16:0"]}
  ],
  "company_features_used": ["F:MAINOKVED_NAME", "F:RAW_MATERIALS", "F:KEY_SUPPLIERS", "F:KEY_CLIENTS", "F:CL_PRODUCT_LOA_MARK", "G:group_3_sb", "P:U_9000006", "P:U_9000007", "P:U_9000008", "P:U_9000025"],
  "data_gaps": [
    "Нет данных о структуре закупок компании по видам топлива (доля бензина vs дизеля) — эффект запрета касается только бензина",
    "Нет аналитики Альфа-Банка непосредственно по топливному рынку и ценам на бензин",
    "Нет данных о маржинальности компании и её ценовой политике на АЗС"
  ]
}
